#include <stddef.h>
#include <stdint.h>
static size_t put_i64(int64_t x,uint8_t*out,size_t p){if(x<0){out[p++]='-';x=-x;}uint8_t d[20];size_t n=0;do{d[n++]=(uint8_t)('0'+x%10);x/=10;}while(x);while(n)out[p++]=d[--n];return p;}
int64_t number_container_system(const int64_t*v,size_t n,uint8_t*out,size_t cap){if(!v||n<1||v[0]<0||v[0]>32||n!=1+3*(size_t)v[0])return -1;int64_t values[64]={0};uint8_t present[64]={0},buf[128];size_t used=0;for(size_t i=0;i<(size_t)v[0];i++){int64_t op=v[1+3*i],a=v[2+3*i],b=v[3+3*i];if(op==0){if(a<0||a>63||b< -100||b>100)return -1;values[a]=b;present[a]=1;}else if(op==1){if(a< -100||a>100||b!=0)return -1;int64_t found=-1;for(int64_t j=0;j<64;j++)if(present[j]&&values[j]==a){found=j;break;}if(used)buf[used++]=',';used=put_i64(found,buf,used);}else return -1;}if(!out||used>cap)return -2;for(size_t i=0;i<used;i++)out[i]=buf[i];return (int64_t)used;}
